using Microsoft.Xna.Framework;
using System.Text.Json.Nodes;
namespace StarlightSyndicateDemo;
public static class PopulationTestsC
{
 public static void Run()
 {
  SkillCatalog.VerificationAllV=false;int checks=0;void Check(bool ok,string name){if(!ok)throw new Exception("STAGE C FAIL: "+name);checks++;Console.WriteLine("STAGE C PASS: "+name);}
  string? old=Environment.GetEnvironmentVariable("STARLIGHT_SAVE_DIR");string dir=Path.Combine(Path.GetTempPath(),"population-c-"+Guid.NewGuid().ToString("N"));Environment.SetEnvironmentVariable("STARLIGHT_SAVE_DIR",dir);
  try{
   var w=new DemoWorld();w.NewGame(0);w.EnsurePopulationC();w.WalletFunds=100000;Check(w.Population.Pilots.Count==8&&w.Population.Businesses.Count==3,"Visited sector receives eight persistent pilots and three businesses");Check(w.PopulationMoneyErrorC==0,"Opening cash accounted exactly");var identities=w.Population.Pilots.Select(p=>p.Id).ToArray();w.EnsurePopulationC();Check(w.Population.Pilots.Select(p=>p.Id).SequenceEqual(identities),"Repeated visit creates no new pilots or reserves");Check(w.Population.Pilots.All(p=>p.Fit.SkillLevels.Count>=7&&p.Fit.Weapons.Length>0),"Pilots have fitted ships and actual skills");
   string system=w.SystemId;string next=w.Current.Links.First();w.EnsurePopulationC(next);Check(w.Population.Sectors.Count==2&&w.PopulationMoneyErrorC==0,"Adjacent sector initialization is explicitly accounted");var seller=w.Population.Businesses.First(b=>b.Station==system&&b.Kind=="Trader");var buyer=w.Population.Businesses.First(b=>b.Station==next&&b.Kind=="Factory");decimal before=seller.Stock["ammo"],cash=buyer.Wallet;
   var op=w.DispatchShipmentC(seller.Id,buyer.Id,"ammo",50)!;Check(op!=null&&op.Route.First()==system&&op.Route.Last()==next,"Shipment has a legal gate route");Check(seller.Stock["ammo"]==before-50&&buyer.Wallet<cash&&op.Escrow>0,"Dispatch reserves cargo and buyer funds once");Check(w.PopulationMoneyErrorC==0,"Escrow conserves cash at dispatch");
   w.EnterGrid(w.Population.Sectors[system].Belt,false);w.BindPopulationGridC();w.BindPopulationGridC();Check(w.Targets.Count(t=>t.Id==op.Pilot)==1,"Repeated materialization has exactly one physical hauler");Check(ReferenceEquals(w.Targets.Single(t=>t.Id==op.Pilot).Profile,w.PopulationPilot(op.Pilot)!.Fit),"Physical ship uses its persistent fitted instance");Check(op.State=="On grid"&&op.Cargo["ammo"]==50,"Materialization retains single authoritative shipment cargo");
   w.Screen=ViewMode.Station;decimal received=buyer.Stock["ammo"];w.AdvancePopulationC(1200);Check(op.State=="Delivered"&&buyer.Stock["ammo"]>=received+50,"Offscreen route delivers real reserved cargo");decimal delivered=buyer.Stock["ammo"];Check(!w.ResolveShipmentC(op.Id,false)&&buyer.Stock["ammo"]==delivered,"Delivered shipment cannot settle twice");Check(w.PopulationMoneyErrorC==0,"Delivery cash conserved");
   var loss=w.DispatchShipmentC(seller.Id,buyer.Id,"ammo",20)!;Check(loss!=null,"Second finite shipment can dispatch");string pilotId=loss.Pilot;string shipId=w.PopulationPilot(pilotId)!.Fit.InstanceId;Check(w.ResolveShipmentC(loss.Id,true)&&loss.State=="Lost"&&loss.Cargo.Count==0,"Interception clears authoritative cargo");Check(w.Population.Debris.Single(d=>d.Id=="debris-c:"+loss.Id).Contents["ammo"]==10,"One wreck retains exactly half the cargo");Check(!w.ResolveShipmentC(loss.Id,true)&&w.Population.Debris.Count(d=>d.Id=="debris-c:"+loss.Id)==1,"Loss and wreck cannot duplicate");Check(w.PopulationPilot(pilotId)!.Fit.Hull==0&&w.PopulationPilot(pilotId)!.Losses==1,"Ship loss persists on named pilot");Check(w.PopulationMoneyErrorC==0,"Lost shipment refunds reserved money exactly");
   var lostPilot=w.PopulationPilot(pilotId)!;var owner=w.Population.Businesses.Single(b=>b.Id==lostPilot.Company);decimal hulls=owner.Stock[DemoWorld.PopulationHullC];Check(w.ReplacePopulationShipC(pilotId)&&owner.Stock[DemoWorld.PopulationHullC]==hulls-1&&lostPilot.Fit.InstanceId!=shipId,"Reship consumes one hull and creates new ship identity");Check(lostPilot.Cargo.GetValueOrDefault(DemoWorld.PopulationAmmoC)+lostPilot.Fit.Weapons[0].Loaded==120,"Replacement magazine and reserve share the purchased ammunition");lostPilot.Fit.Hull=0;owner.Stock[DemoWorld.PopulationHullC]=0;Check(!w.ReplacePopulationShipC(pilotId)&&lostPilot.Status=="Awaiting supplies","No free reship when hull stock is empty");
   var recruit=w.Population.Pilots.First(p=>p.System==system&&p.Role=="Tackler");decimal playerMoney=w.Balance,crewCash=recruit.Wallet;Check(w.HirePopulationPilotC(recruit.Id)&&w.Balance==playerMoney-350&&recruit.Wallet==crewCash+350,"Recruitment transfers real contract funds");Check(w.FleetMember(recruit.Id),"Recruited pilot participates in fleet eligibility");Check(w.OrderPopulationC("Hold")&&recruit.Order=="Hold","Squad hold orders persist");Check(!w.OrderPopulationC("Attack"),"Attack without selected target rejected");long paid=recruit.PaidThrough;w.AdvancePopulationC(Math.Max(0,paid-w.Population.Tick)*60);Check(recruit.PaidThrough>paid&&!recruit.Suspended,"Hourly wage paid on simulated clock");w.WalletFunds=0;w.AdvancePopulationC(3600);Check(recruit.Suspended,"Unpaid contract suspends service");Check(w.PopulationMoneyErrorC==0,"Contract and wages conserve managed cash");
   w.WalletFunds=100000;foreach(var company in w.Population.Businesses)w.CancelBusinessOrdersC(company);w.MarketOrders.Clear();w.PublishBusinessOrdersC();Check(w.PopulationMoneyErrorC==0,"Market reservations conserve goods-backed cash");var order=w.MarketOrders.Where(o=>!o.Buy&&o.BusinessC.Length>0&&o.Station==system&&o.Item=="ammo"&&o.Remaining>=2).OrderBy(o=>o.Price).ThenBy(o=>o.Created).First();decimal available=order.Remaining;string result=w.SubmitMarket("ammo",system,true,2,order.Price,0,true);Check(result.StartsWith("Trade complete")&&order.Remaining==available-2,"Existing market consumes actual business sell reserve");Check(w.PopulationMoneyErrorC==0,"Business market trade reconciles tax and external cash");w.Hangar["ammo"]=100;Check(w.SupplyBusinessC(seller.Id,"ammo",100)&&w.Hangar["ammo"]==0,"Player supply sale consumes actual hangar ammunition");Check(w.PopulationMoneyErrorC==0,"Supply sale conserves cash");
   var emptyFactory=w.Population.Businesses.First(b=>b.Kind=="Factory");emptyFactory.Stock.Clear();long runs=emptyFactory.Runs;w.Population.Businesses.Where(b=>b.Id!=emptyFactory.Id).ToList().ForEach(b=>b.Stock.Clear());w.AdvancePopulationC(300);Check(emptyFactory.Runs==runs&&emptyFactory.Shortages>0,"Missing inputs delay manufacturing without spawned stock");
   w.Screen=ViewMode.Space;w.Grid=w.Population.Sectors[system].Belt;w.Targets.Clear();w.BindPopulationGridC();var kite=w.Population.Pilots.First(p=>p.System==system&&p.Role=="Pirate");var target=w.Targets.Single(t=>t.Id==kite.Id);w.Player.Position=Vector3.Zero;target.Position=new(1000,0,0);target.Cap=kite.Fit.MaxCap;kite.Target="player";kite.Knowledge["player"]=w.Now.AddSeconds(20);w.UpdatePopulationTacticsC(.1f);Check(target.Velocity.X>0,"Kiter increases separation inside preferred range");
   target.Cap=kite.Fit.MaxCap;target.Shield=1;target.Armor=1;target.Hull=1;w.UpdatePopulationTacticsC(.1f);Check(kite.Retreated&&kite.Status=="Retreating"&&!w.Targets.Any(t=>t.Id==kite.Id),"Outmatched ship retreats when not tackled");
   recruit.Suspended=false;recruit.Order="Follow";recruit.System=system;w.BindPopulationGridC();var tackle=w.Targets.Single(t=>t.Id==recruit.Id);tackle.Position=new(1500,0,0);tackle.Cap=recruit.Fit.MaxCap;recruit.Target="player";recruit.Knowledge["player"]=w.Now.AddSeconds(20);w.UpdatePopulationTacticsC(.1f);Check(w.EwarFor("player").WarpStrength>0,"Fitted tackler applies shared EWAR effect");
   w.EwarEffects.Clear();foreach(var module in recruit.Fit.Ewar){module.Online=false;module.Cooldown=0;}w.UpdatePopulationTacticsC(.1f);Check(w.EwarFor("player").WarpStrength==0,"Offline NPC tackle cannot apply an effect");foreach(var module in recruit.Fit.Ewar)module.Online=true;w.Targets.Add(new(){Id="unseen",Kind=TargetKind.Raider,Position=new(10000000,0,0),Profile=new Ship()});recruit.Target="unseen";recruit.Knowledge.Clear();w.UpdatePopulationTacticsC(.1f);Check(tackle.LockId.Length==0,"Unobserved distant targets are not acquired omnisciently");
   w.Screen=ViewMode.Station;w.Save();var saved=new DemoWorld();Check(saved.Load(),"Population save loads");Check(saved.Population.Pilots.Select(p=>p.Id).SequenceEqual(w.Population.Pilots.Select(p=>p.Id)),"Stable pilot identity survives reload");Check(saved.Population.Shipments.Single(o=>o.Id==loss.Id).State=="Lost"&&saved.Population.Debris.Single(d=>d.Id=="debris-c:"+loss.Id).Contents["ammo"]==10,"Shipment loss and one wreck survive reload");Check(saved.PopulationMoneyErrorC==0,"Reload preserves financial reconciliation");Check(saved.Population.Pilots.Single(p=>p.Id==recruit.Id).Contracted,"Crew contract survives reload");
   var a=new DemoWorld();a.NewGame(0);a.EnsurePopulationC();var bWorld=new DemoWorld();bWorld.NewGame(0);bWorld.EnsurePopulationC();a.AdvancePopulationC(600);for(int i=0;i<10;i++)bWorld.AdvancePopulationC(60);Check(a.Population.Tick==bWorld.Population.Tick&&a.Population.Businesses.Select(b=>b.Runs).SequenceEqual(bWorld.Population.Businesses.Select(b=>b.Runs)),"Strategic results independent of incoming time partition");
   var staleSector=a.Population.Sectors[a.SystemId];a.Targets.Add(new(){Id="resource-c:"+a.SystemId,Kind=TargetKind.Asteroid,Ore=50000});int resourceBefore=staleSector.Resource;a.AdvancePopulationC(120);Check(staleSector.Resource==resourceBefore-20,"Docked stale grid cannot replenish finite ore or suppress offscreen mining");var pause=a.Population.Tick;a.SimulationPaused=true;a.Update(10);Check(a.Population.Tick==pause,"Pause freezes strategic population");a.SimulationPaused=false;a.MarketOrders.Clear();a.AdvancePopulationC(7*24*3600);Check(a.Population.Shipments.Any(o=>o.State=="Delivered"),"Autonomous supply jobs move real stock without fixture dispatch");Check(a.PopulationMoneyErrorC==0,"Seven-day accelerated economy conserves managed cash");Check(a.Population.Businesses.All(b=>b.Wallet>=0&&b.Stock.Values.All(q=>q>=0)),"Long run has no negative inventories or budgets");Check(a.Population.Sectors.Values.All(s=>s.Resource>=0)&&a.Population.Journal.Count<=800,"Long run preserves finite resource and bounded journal");
   a.PublishBusinessOrdersC();a.AdvanceHours(91*24);Check(a.PopulationMoneyErrorC==0,"Expired business orders release reserves without losing escrow");var json=JsonNode.Parse(File.ReadAllText(DemoWorld.SavePath))!;json["SaveSchemaVersion"]=47;json.AsObject().Remove("Population");File.WriteAllText(DemoWorld.SavePath,json.ToJsonString());var migrated=new DemoWorld();Check(migrated.Load()&&File.Exists(DemoWorld.SavePath+".pre-stage-c.bak"),"Stage B save migrates with exact backup and population initialization");
   Console.WriteLine(checks+" Stage C checks passed.");
  }finally{Environment.SetEnvironmentVariable("STARLIGHT_SAVE_DIR",old);if(Directory.Exists(dir))Directory.Delete(dir,true);}
 }
}
